metric_col = '{{metric_column}}'
segment_col = '{{segment_column}}'

if segment_col not in df.columns:
    print(f'segment column {segment_col!r} not in csv — skipping')
else:
    by = df.groupby([segment_col, 'variant'])[metric_col].agg(['mean', 'count']).unstack('variant')
    means = by['mean']
    if 'control' in means and 'treatment' in means:
        means['rel_lift_%'] = (means['treatment'] - means['control']) / means['control'] * 100
    means.round(4)
